import { desc, eq } from 'drizzle-orm'
import { redirect } from 'next/navigation'
import { approvedVendorForCurrentUser } from '@/lib/vendor-auth'
import { db } from '@/lib/db'
import { vendorNotifications } from '@/lib/db/schema'
export default async function VendorNotificationsPage(){const access=await approvedVendorForCurrentUser();if(!access)redirect('/vendor/login');const rows=await db.select().from(vendorNotifications).where(eq(vendorNotifications.vendorId,access.vendor.id)).orderBy(desc(vendorNotifications.createdAt));return <main className="min-h-screen bg-[#f8f5ee] px-4 py-8"><div className="mx-auto max-w-4xl"><h1 className="font-serif text-4xl">Notifications</h1><section className="mt-6 rounded-[24px] bg-white">{rows.length===0?<p className="p-5">No notifications yet.</p>:rows.map(item=><article key={item.id} className="border-b p-5"><h2 className="font-serif text-xl">{item.title}</h2><p className="mt-1 text-sm text-[#59645f]">{item.message}</p></article>)}</section></div></main>}